////  CityViewModel.swift//  YP_Trains//import SwiftUIimport Combineimport OpenAPIURLSessionclass CityViewModel: ObservableObject {    @Published var searchText = ""    @Published var allCities: [CityModel] = []    @Published var filteredCities: [CityModel] = []    // Используем @ObservedObject для кэш-менеджера    private var cacheManager = CachedDataManager.shared    private let yaApiKey = Config.shared.getApiKey()    init() {        loadCities()    }    private func loadCities() {        print(allCities)        Task {            if allCities.isEmpty {                await fetchStationsIfNeeded()            }        }    }    private func fetchStationsIfNeeded() async {        // Проверяем, есть ли данные в кэше        let cachedCities = cacheManager.getCachedCities()        // Если нет кэша или кэш пуст - загружаем с API        guard let cities = cachedCities, !cities.isEmpty else {            print("Загрузка данных из API...")            do {                try await loadInitialData()                print("Данные успешно загружены в кэш")            } catch {                print("Ошибка при загрузке данных: \(error)")            }            return        }        // Используем данные из кэша        allCities = cities        filterCities() // Обновляем фильтрованный список    }        private func loadInitialData() async {        let yaApiKey = Config.shared.getApiKey()          do {            let client = Client(                serverURL: try Servers.Server1.url(),                transport: URLSessionTransport()            )            let allCity = AllStationsService(client: client, apikey: yaApiKey)            try await allCity.getAllStations()            print("Данные успешно загружены в кэш")        } catch {            print("Ошибка при загрузке данных: \(error)")        }    }        func filterCities() {        if searchText.isEmpty {            filteredCities = allCities        } else {            filteredCities = allCities.filter {                $0.title.localizedCaseInsensitiveContains(searchText)            }        }    }    func clearSearch() {        searchText = ""        filterCities()    }}